SourceCode.Declaration:
/// <summary>
/// Applies the CELT field setup (E-Invoice > Setup > E-Invoice field setup) to the standard forms
/// that carry CELT custom input controls. Every extension control follows the naming convention
/// CELT_&lt;FieldNameWithoutCELT&gt; (e.g. CELT_AETransactionType binds CELTAETransactionType), so one
/// generic pass over the form design hides exactly the controls whose field is disabled. Controls
/// without a setup row (containers like CELT_EInvoiceTab, or new fields not seeded yet) stay
/// visible - the setup can only hide, never break, a form.
/// </summary>
internal final class CELTFieldSetupVisibility
{
}

Method.Source:
/// <summary>
/// Hides every CELT_* control on the form whose field is disabled for the given area in the
/// field setup. Driven from the setup rows and resolved by control NAME (design().controlName
/// searches the whole design) - iterating design().controlNum() only walks top-level controls
/// and never reaches fields nested in FastTabs.
/// </summary>
/// <param name = "_sender">the form being opened</param>
/// <param name = "_area">the document area the form belongs to (Any = show when enabled anywhere)</param>
public static void apply(xFormRun _sender, CELTFieldArea _area = CELTFieldArea::Any)
{
    CELTFieldSetup setup;
    FormDesign     design = _sender.design();

    while select FieldName, EnabledSales, EnabledPurchase, EnabledProject from setup
    {
        boolean enabled;

        switch (_area)
        {
            case CELTFieldArea::Sales:
                enabled = setup.EnabledSales == NoYes::Yes;
                break;
            case CELTFieldArea::Purchase:
                enabled = setup.EnabledPurchase == NoYes::Yes;
                break;
            case CELTFieldArea::Project:
                enabled = setup.EnabledProject == NoYes::Yes;
                break;
            default:
                enabled = setup.EnabledSales == NoYes::Yes
                       || setup.EnabledPurchase == NoYes::Yes
                       || setup.EnabledProject == NoYes::Yes;
        }

        if (!enabled)
        {
            // Field CELT<X> binds to control CELT_<X> by convention on every extended form.
            FormControl control = design.controlName('CELT_' + subStr(setup.FieldName, 5, strLen(setup.FieldName) - 4));

            if (control)
            {
                control.visible(false);
            }
        }
    }
}

[FormEventHandler(formStr(SalesTable), FormEventType::Initialized)]
public static void SalesTable_OnInitialized(xFormRun sender, FormEventArgs e)
{
    CELTFieldSetupVisibility::apply(sender, CELTFieldArea::Sales);
}

